package com.tripmateai.entity;
import com.tripmateai.enums.ReviewType; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*;
@Entity @Table(name="reviews",indexes={@Index(name="idx_reviews_user",columnList="user_id"),@Index(name="idx_reviews_type",columnList="review_type")}) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class Review extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @Enumerated(EnumType.STRING) @Column(name="review_type",nullable=false,length=30) private ReviewType reviewType; @Min(1) @Max(5) @Column(nullable=false) private Integer rating; @Size(max=5000) @Column(columnDefinition="TEXT") private String comment; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="destination_id") @ToString.Exclude private Destination destination; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="hotel_id") @ToString.Exclude private Hotel hotel; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="restaurant_id") @ToString.Exclude private Restaurant restaurant; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="attraction_id") @ToString.Exclude private Attraction attraction; }
